-- Estrutura mínima derivada dos modelos/DAOs; somente em PostgreSQL descartável.
CREATE TABLE "USUARIOS" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome text, email text UNIQUE, telefone text, datanasc date, senha text, perfil text, status boolean DEFAULT true, created_at timestamp DEFAULT now());
CREATE TABLE "ALUNOS" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at timestamp DEFAULT now(), rgm text, id_usuario bigint REFERENCES "USUARIOS"(id));
CREATE TABLE "PROFESSORES" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, matricula text, created_at timestamp DEFAULT now(), id_usuario bigint REFERENCES "USUARIOS"(id));
CREATE TABLE "ADMINISTRADOR" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_usuario bigint REFERENCES "USUARIOS"(id), created_at timestamp DEFAULT now(), matricula text);
CREATE TABLE "TURMAS" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome_turma text, id_professores bigint[], id_alunos bigint[], created_at timestamp DEFAULT now(), id_proprietario bigint, descricao text);
CREATE TABLE "ALUNO_TURMA" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_aluno bigint, id_turma bigint, situacao_aluno text DEFAULT 'ativo', created_at timestamp DEFAULT now());
CREATE TABLE "PROFESSOR_TURMA" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_professor bigint, id_turma bigint, created_at timestamp DEFAULT now());
CREATE TABLE "DISPONIBILIDADES" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_aluno bigint NOT NULL, data date NOT NULL, horas_disponiveis integer NOT NULL, created_at timestamp DEFAULT now(), UNIQUE(id_aluno,data));
CREATE TABLE "DENUNCIAS" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_conteudo bigint, id_aluno bigint, id_professor bigint, motivo text, status text DEFAULT 'pendente', created_at timestamp DEFAULT now());
CREATE TABLE "CONTEUDOS" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_turma bigint[], id_professor bigint, created_at timestamp DEFAULT now(), titulo text, descricao text, tipo text, duracao_estimada text, prioridade text, status text, revisao_solicitada boolean DEFAULT false, url text, comentario_admin text, revisao_solicitada_em timestamp);
CREATE TABLE "EVENTOS" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_turma bigint, id_professor bigint, titulo text, tipo text, descricao text, data_hora timestamp, status text, created_at timestamp DEFAULT now(), data_fim timestamp, prioridade text);
CREATE TABLE "EVENTO_CONTEUDO" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_evento bigint, id_conteudo bigint);
CREATE TABLE "ARQUIVOS" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, id_conteudo bigint, created_at timestamp DEFAULT now(), bucket_id text, storage_path text, nome_original text, content_type text, tamanho bigint);
CREATE TABLE "LOGS_SESSOES" (sessao_log_id uuid PRIMARY KEY, usuario_id bigint, inicio timestamp, fim timestamp, status text DEFAULT 'ATIVA', log_completo text, historico_gerado_em timestamp);
CREATE TABLE "LOGS_EVENTOS" (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sessao_log_id uuid, nivel text, classe text, operacao text, operacao_id uuid, mensagem text, detalhes jsonb, excecao text, data_hora timestamp DEFAULT clock_timestamp());
